"""Render the lead's evidence-backed bounded decisions into per-target reports and RESULTS.csv."""
import csv,json
from pathlib import Path
B=Path(__file__).resolve().parent
Q=list(csv.DictReader((B/'queue.csv').open(newline='',encoding='utf-8')))
G={x['tic']:x for x in json.loads((B/'helper-gaia-covariance.json').read_text())}
N={x['tic']:x for x in json.loads((B/'helper-neighbors-all.json').read_text())}
S={x['tic']:x for x in json.loads((B/'helper-spatial.json').read_text())+json.loads((B/'helper-spatial-rest.json').read_text())}
V={
'T001':dict(verdict='PROBABLE',period='28.035775',error='0.000020',epoch='1819.3843',depth='176',limits='A Gaia neighbor 2.71 arcsec away could produce the observed loss; the TESS difference centroid cannot resolve it.',next='Resolve the target and close Gaia neighbor with high-resolution in-eclipse imaging.',finding='Many raw eclipses recur in two distinct kinds over sectors 15–85. The deep kind repeats at 28.035775 d; the shallow kind independently gives 28.035757 d. The 4.66-d separation of kinds is compatible with the strongly eccentric Gaia orbit. The 2.71-arcsec neighbor is bright enough that its eclipse could make the observed blended deficit, so source ownership remains open.'),
'T002':dict(verdict='PROBABLE',period='24.620831',error='0.000050',epoch='1435.0298',depth='127',limits='Gaia conjunction differs by about 3.1 linear sigma at the old event and 2.8 sigma at the new event, despite strong photometric recurrence and target-centered pixel flux. The Gaia orbit or source association needs reconciliation.',next='Obtain radial velocities and a new eclipse to compare the 24.620831-d photometric clock with the Gaia spectroscopic orbit.',finding='Two clean QLP raw eclipses in sectors 4 and 31 are joined by two full target-centered raw-pixel events in newly available sectors 105 and 108; an additional S108 event at the sector start is partial support. The 29-cycle old assignment yields 24.620831 d across four full centers; 28- and 30-cycle alternatives predict flat, sensitive windows in sectors 105/108. A fully covered sector-108 P/2 prediction is also flat. The binary-like eclipse recurs, but Gaia conjunction timing remains in tension.'),
'T003':dict(verdict='CONFIRMED',period='48.527672',error='0.000327',epoch='3953.4326',depth='137',limits='The two same-kind deep centers give a conditional five-cycle clock; two shallow events over 53 cycles independently agree. Long-baseline Gaia covariance is linearized.',next='Acquire another primary eclipse to sharpen the clock and orbit comparison.',finding='Deep raw eclipses recur in sectors 97 and 104 five cycles apart. Shallow eclipses in sectors 3 and 97 give 48.527215 d over 53 cycles, agreeing with the 48.527672-d deep clock. The two kinds are separated by the eccentric-orbit phase; their independent cycle spans address aliases.'),
'T004':dict(verdict='CONFIRMED',period='38.115712',error='0.000500',epoch='3070.0045',depth='118',limits='The sector-102 deep event contains a 0.243-d data gap; its center is inferred from surviving ingress and egress. The 0.0005-d period allowance is conservative relative to the formal fit covariance. The shallow sector-65 fit covariance is singular and its center is not precision evidence.',next='Obtain one uninterrupted deep eclipse for a cleaner center and period.',finding='Deep raw eclipses in sectors 65 and 102 are 28 cycles apart at 38.115712 d. Shallow events around 3090.5 and 4119.56, 27 cycles apart, support the same orbit at the opposite conjunction. The sector-102 gap limits timing precision but does not erase its ingress and egress.'),
'T005':dict(verdict='CONFIRMED',period='28.028754',error='0.000500',epoch='1577.7953',depth='60',limits='Long local baseline trends affect depth and timing; the 0.0005-d period allowance exceeds the formal deep-fit scatter. QLP corrected flux suppresses the event. The TESSCut reduction reproduces it at lower dilution-dependent depth.',next='Obtain additional short-cadence eclipses with stable aperture photometry.',finding='Deep raw eclipses recur in adjacent sectors 10–11 and 64–65, with shallow opposite-conjunction dips near half phase. The deep centers give 28.028754 d and the shallower kind independently gives 28.027860 d, with local-trend timing limitations.'),
'T006':dict(verdict='CONFIRMED',period='43.062062',error='0.004910',epoch='2183.2390',depth='33',limits='Only two observed eclipse centers; the period allowance is driven by half-cadence timing and does not calibrate model systematics.',next='Observe a third eclipse to refine the period.',finding='Two clean raw eclipses in sectors 32 and 33 are 43.062 d apart. The two-cycle alias predicts a fully observed midpoint at BTJD 2204.770 with only 0.17 ppt deficit; three- and four-cycle aliases likewise predict a clean null. This supports one orbital cycle between the events.'),
'T007':dict(verdict='PLAUSIBLE',period='',error='',epoch='',depth='',limits='Broad dips ride changing baseline slopes; S34 and S61 have missing ingress or baseline, so centers are not precise. The 18/19/20-cycle interpretations of the long separation all predict the roughly third-spaced partial occasions. A narrow deep event occurs only in S88. New S109 has changing baseline and edge windows, not a decisive alias test.',next='Observe an uninterrupted shallow and deep eclipse pair to establish morphology, source and integer cycle count.',finding='Broad shallow depressions appear in sectors 7, 34, 61 and 88, roughly 38.88 d apart under one cycle assignment, but the sector-34 and sector-61 occasions are partly gapped and have strong changing baselines. The sector-61 post-gap egress is real positive recurrence evidence yet does not choose among 18/19/20-cycle long-baseline aliases. A deeper narrow S88 dip occurs near opposite phase. The eclipse interpretation and clock remain insecure.'),
'T008':dict(verdict='PLAUSIBLE',period='',error='',epoch='',depth='',limits='One broad raw event has a central 1.6-d gap, so its center and depth are not secure. The sector-62 TESSCut is on a zero-pixel detector edge and cannot test the source. New sector 109 is flat only in BTJD 4318.56–4338.74.',next='Get a target-centered alternative reduction and another eclipse occasion.',finding='Sector 62 shows ingress, a central data gap, and a strong recovery compatible with a broad eclipse; its fitted center at the gap edge is not a measured minimum. No same-kind repeat is established in the cached sectors. A newer sector-109 cutout covers a bounded flat interval, but that interval does not test all period aliases.'),
'T009':dict(verdict='CONFIRMED',period='42.568962',error='0.000487',epoch='2330.4867',depth='18',limits='A sector-37 opposite-kind center fit has singular covariance and is excluded. Sector-99 broad variability is not used as a precise eclipse center.',next='Observe another clean eclipse in each kind to improve timing and assess depth changes.',finding='Repeated raw eclipses form two distinct kinds. Kind A recurs in sectors 37, 64 and 100 with a 42.568962-d clock; kind B in sectors 64 and 90 gives 42.568189 d. The second kind and multiple cycle baselines support recurrence and reject a score-only interpretation.'),
'T010':dict(verdict='REFUTED',period='',error='',epoch='',depth='',limits='The sector-88 QLP rectangle is contradicted by simultaneous target-centered TESSCut flux; its QLP aperture/background origin is unresolved. Sector-109 cutout has near-zero target flux and supplies no sensitive null.',next='Inspect the QLP sector-88 aperture and background pixels to identify the rectangular signal origin.',finding='QLP SAP has a 31.19-ppt rectangular loss in sector 88. A target-centered TESSCut 3x3 with 5552-count baseline, using the same 103 core and 129-cadence flank windows, has −1.10-ppt loss and remains flat. This is positive contrary evidence for an eclipse on the selected Gaia target. It does not show that the star cannot be a binary or identify the source of the QLP rectangle.')
}
fields=['sample_id','tic','sample_stratum','physical_verdict','full_review_completion','novelty_status','period_days','period_error_days','primary_epoch_btjd','depth_ppt','limitations','next_check','report']
rows=[]
for q in Q:
    sid=q['sample_id']; tic=q['tic'];v=V[sid];m=json.loads((B/tic/'lead-numeric.json').read_text());tm=json.loads((B/tic/'lead-timing.json').read_text());g=G[tic];n=N[tic];s=S[tic]
    report=B/tic/'REPORT.md'
    lines=[f'# {sid}: TIC {tic}', '',f'**Physical verdict:** {v["verdict"]}. **Bounded review:** COMPLETE. **Novelty:** UNKNOWN (shared catalogue gates, not inferred from physical evidence).','',v['finding'],'','## Raw events and recurrence','',f'Source FITS checked by SHA-256; {len(m["coverage"])} cached sectors, {len(m["events"])} retained dip windows re-examined in quality-zero raw SAP. Screening windows were predictions, not eclipse centers. All retained-window plots are `lead-raw-*.png`; numeric source receipts and local-fit diagnostics are `lead-numeric.json`.','', '| Sector | Screen BTJD | Fit BTJD | Raw deficit (ppt) | Fit caveat |','|---:|---:|---:|---:|---|']
    for e in m['events']:
        caveat='finite' if (e.get('fit_mid_formal_error_days') or 1e99)<.1 else 'unusable covariance/shape'
        lines.append(f"| {e['sector']} | {e['screen_btjd']:.3f} | {e.get('fit_mid_btjd',float('nan')):.4f} | {e.get('raw_core_median_deficit_ppt',float('nan')):.1f} | {caveat} |")
    if sid=='T002':
        new=json.loads((B/tic/'lead-new-timing.json').read_text()); cov=json.loads((B/'lead-newsector-coverage.json').read_text());geom=json.loads((B/tic/'lead-new-geometry.json').read_text())
        lines+=['','New sector-105/108 target-centered 3x3 raw-pixel events (not QLP rows):']
        for x in new['events']:lines.append(f"- S{x['sector']} center {x['center_btjd']:.5f}, depth {x['depth_ppt']:.1f} ppt, baseline {x['ap3_baseline']:.0f} counts; S108 4291 event begins near sector edge and is supporting timing only.")
        lines.append(f"- P/2 predicted BTJD {new['half_period_null']['predicted_btjd']:.4f}: {new['half_period_null']['quality0_core_n']} quality-zero core cadences, {new['half_period_null']['quality0_left_n']}/{new['half_period_null']['quality0_right_n']} flanks, {new['half_period_null']['core_median_deficit_ppt']:+.2f} ppt versus ~127-ppt events. S107 target aperture has ~0.6-count baseline and is not a sensitive null.")
        lines.append(f"- Gaia nearest conjunction at new S108 center differs by {geom['closest']['offset_days']:+.2f} d / {geom['closest']['linear_sigma_days']:.2f} d linear sigma ({geom['closest']['offset_in_sigma']:+.2f} sigma). Source-specific covariance does not remove the timing tension.")
        lines.append('`lead-newsector-coverage.json` records all 28/29/30-cycle predictions with core endpoints, internal gaps, flank counts, aperture flux and source hashes; only sensitive nulls were used to reject aliases.')
    if sid in ('T003','T004'):
        alias=json.loads((B/'lead-short-alias.json').read_text());z=next(x for x in alias if x['sample_id']==sid and x['alias_divisor']==2)
        lines+=['',f"Shorter P/2 deep-event alias at BTJD {z['predicted_deep_btjd']:.4f} has {z['quality0_core_n']}/{z['expected_core_n']:.0f} expected quality-zero core samples, {z['quality0_left_n']}/{z['quality0_right_n']} flank samples, a {z['core_max_internal_gap_days']:.4f}-d largest core gap and {z['core_median_deficit_ppt']:+.2f}-ppt core deficit versus a >100-ppt deep eclipse. The recorded gross-event sensitivity excludes a missed counterpart there; `lead-short-alias.json` and plot retain stricter coverage flags and additional P/3/P/4 checks."]
    if sid=='T007':
        a=json.loads((B/tic/'lead-alias.json').read_text());lines+=['',f"Sector 61 partial occasion: at predicted BTJD {a['predicted_s61_btjd']:.3f}, quality-zero core {a['quality0_core_n']}/{a['expected_core_n']:.0f} expected samples with missing ingress, {a['core_median_deficit_ppt']:.1f}-ppt median deficit and {a['side_scatter_ppt']:.1f}-ppt flank scatter. The observed post-gap egress supports recurrence but does not count integer cycles. Newly fetched S109 has nonzero target flux but trend-dominated edge predictions; see `lead-newsector-coverage.json`."]
    lines+=['','## Clock and orbit','']
    for kind,t in tm['kinds'].items(): lines.append(f"- {kind}: {t['period_days']:.6f} d from sectors {', '.join(map(str,t['sector']))}, integer cycles {', '.join(map(str,t['cycle']))}; timing allowance {t['period_error_days']:.6f} d ({t['error_meaning']}).")
    if not tm['kinds']:lines.append('- No repeat clock is measured.')
    c=g['closest'];lines.append(f"- Gaia DR3 SB1 orbit: P={float(q['gaia_period_days']):.5f} d. Nearest edge-on conjunction at evaluation BTJD {g['evaluation_epoch_btjd']:.4f} differs by {c['offset_days']:+.3f} d, with source-specific linear covariance sigma {c['linear_sigma_days']:.3f} d ({c['offset_in_sigma']:+.2f} sigma). This is a compatibility check, not proof of source ownership.")
    spatial_note=(f"WCS difference centroid is {s['offset_pix']:.3f} TESS pixels from the target; custom TESSCut depth is {s['depth_ppt']:.2f} ppt." if s.get('offset_pix') is not None and s.get('depth_ppt') is not None else 'A valid difference centroid is unavailable in the checked TESSCut aperture.')
    if sid=='T008':spatial_note+=' The cutout lies on the detector edge with zero-valued pixels, so its negative fixed-window difference is not a sensitive refutation.'
    if sid=='T010':spatial_note+=' The narrower, target-centered 3x3 simultaneous check in `helper-T010-comparison.png` is decisive; the broad 5x5 difference statistic is not used.'
    if sid=='T005':spatial_note+=' The nearest G-capable Gaia neighbor is 1.91 pixels from the loss centroid, versus 0.078 pixel for the target.'
    if sid=='T009':spatial_note+=' The nearest G-capable Gaia neighbor is 1.86 pixels from the loss centroid, versus 0.321 pixel for the target.'
    lines+=['','## Source and independent reduction','',f"{spatial_note} Same-photon TESSCut extraction is an independent reduction, not another observing occasion. {len(n['capable'])} Gaia neighbors within 120 arcsec pass the optimistic G-band full-throughput disappearance screen; neighbor positions and flux-ratio assumptions are in `helper-neighbors-all.json`.",'',f'**Limitations:** {v["limits"]}','',f'**Next check:** {v["next"]}','','## Evidence','',f'- `lead-numeric.json`, `lead-timing.json`, and `lead-raw-*.png`: raw SAP and timing.', '- `../helper-spatial.json`, `../helper-spatial-rest.json`, `../helper-neighbors-all.json`, `../helper-gaia-covariance.json`: independent pixel, neighbor, orbital checks.', '- `../../source-packets/'+tic+'/sources.json`: frozen bulk and FITS provenance.']
    report.write_text('\n'.join(lines)+'\n',encoding='utf-8')
    rows.append(dict(sample_id=sid,tic=tic,sample_stratum=q['sample_stratum'],physical_verdict=v['verdict'],full_review_completion='COMPLETE',novelty_status='UNKNOWN',period_days=v['period'],period_error_days=v['error'],primary_epoch_btjd=v['epoch'],depth_ppt=v['depth'],limitations=v['limits'],next_check=v['next'],report=str(report)))
with (B/'RESULTS.csv').open('w',newline='',encoding='utf-8') as f:
    w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerows(rows)
print('wrote',len(rows),'reports and RESULTS.csv')
